POSTGRES_SQL = "CREATE OR REPLACE FUNCTION trg_declared_booking_source_fn() RETURNS trigger AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.normalized_plate,0)); PERFORM id FROM vehicles v WHERE replace(replace(replace(upper(v.license_plate),'-',''),'.',''),' ','')=NEW.normalized_plate ORDER BY id FOR NO KEY UPDATE; PERFORM id FROM parking_slots WHERE id=NEW.slot_id FOR UPDATE; IF NEW.status!='confirmed' OR NEW.session_id IS DISTINCT FROM NULL OR NEW.normalized_plate!=replace(replace(replace(upper(NEW.license_plate),'-',''),'.',''),' ','') OR NOT (EXISTS (SELECT 1 FROM parking_slots s JOIN zones z ON z.id=s.zone_id\n JOIN parking_sites p ON p.id=z.site_id JOIN vehicle_types t ON t.id=s.vehicle_type_id\n JOIN users u ON u.id=NEW.user_id JOIN roles role ON role.id=u.role_id\n WHERE s.id=NEW.slot_id AND z.site_id=NEW.site_id AND t.id=NEW.vehicle_type_id\n AND s.is_active AND z.is_active AND p.is_active AND t.is_active AND u.is_active\n AND role.name='customer' AND NOT s.is_occupied)\n AND NOT EXISTS (SELECT 1 FROM parking_sessions s WHERE s.parking_slot_id=NEW.slot_id AND s.status IN ('active','checking_out'))) OR EXISTS (SELECT 1 FROM declared_parking_reservations r WHERE\n (r.slot_id=NEW.slot_id OR r.normalized_plate=NEW.normalized_plate) AND r.status='confirmed'\n AND r.arrival_deadline>NEW.created_at AND r.end_at>NEW.created_at AND r.start_at<NEW.end_at AND r.end_at>NEW.start_at) OR EXISTS (SELECT 1 FROM parking_reservations r WHERE r.slot_id=NEW.slot_id\n AND (r.status='confirmed' OR (r.status='arrived' AND EXISTS(SELECT 1 FROM parking_sessions s WHERE s.id=r.session_id AND s.status IN ('active','checking_out'))))\n AND r.arrival_deadline>NEW.created_at AND r.start_at<NEW.end_at AND r.end_at>NEW.start_at)\n OR EXISTS (SELECT 1 FROM guaranteed_allocations a WHERE a.slot_id=NEW.slot_id AND a.status='active' AND a.start_at<NEW.end_at AND a.end_at>NEW.start_at)\n OR EXISTS (SELECT 1 FROM parking_capacity_holds h WHERE (h.slot_id=NEW.slot_id OR h.vehicle_id IN (SELECT v.id FROM vehicles v WHERE replace(replace(replace(upper(v.license_plate),'-',''),'.',''),' ','')=NEW.normalized_plate)) AND h.status='held' AND h.expires_at>NEW.created_at AND h.start_at<NEW.end_at AND h.end_at>NEW.start_at) THEN RAISE EXCEPTION 'declared booking capacity or source invalid' USING ERRCODE='23514'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;\nCREATE OR REPLACE FUNCTION trg_declared_session_insert_fn() RETURNS trigger AS $$ BEGIN  IF NEW.status='active' AND (EXISTS (SELECT 1 FROM declared_parking_reservations r JOIN vehicles v ON v.id=NEW.vehicle_id\n WHERE r.status='confirmed' AND r.arrival_deadline>NEW.check_in_time AND r.end_at>NEW.check_in_time\n AND r.slot_id=NEW.parking_slot_id AND r.start_at<COALESCE((SELECT MAX(bound.end_at) FROM (SELECT r.end_at FROM parking_reservations r JOIN vehicles v ON v.id=r.vehicle_id WHERE r.slot_id=NEW.parking_slot_id AND r.vehicle_id=NEW.vehicle_id AND r.customer_id=v.customer_id AND r.status='confirmed' AND r.start_at<=NEW.check_in_time AND r.arrival_deadline>NEW.check_in_time UNION ALL SELECT a.end_at FROM guaranteed_allocations a JOIN vehicles v ON v.id=a.vehicle_id WHERE a.slot_id=NEW.parking_slot_id AND a.vehicle_id=NEW.vehicle_id AND a.customer_id=v.customer_id AND a.status='active' AND a.start_at<=NEW.check_in_time AND a.end_at>NEW.check_in_time UNION ALL SELECT d.end_at FROM declared_parking_reservations d JOIN vehicles v ON v.id=NEW.vehicle_id WHERE d.slot_id=NEW.parking_slot_id AND d.normalized_plate=replace(replace(replace(upper(v.license_plate),'-',''),'.',''),' ','') AND d.vehicle_type_id=v.vehicle_type_id AND d.status='confirmed' AND d.start_at<=NEW.check_in_time AND d.arrival_deadline>NEW.check_in_time AND d.end_at>NEW.check_in_time) bound), '9999-12-31') AND NOT (r.normalized_plate=replace(replace(replace(upper(v.license_plate),'-',''),'.',''),' ','')\n AND r.vehicle_type_id=v.vehicle_type_id AND r.start_at<=NEW.check_in_time))) THEN RAISE EXCEPTION 'slot has declared booking' USING ERRCODE='23514'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;\nCREATE OR REPLACE FUNCTION trg_declared_session_activate_fn() RETURNS trigger AS $$ BEGIN  IF NEW.status='active' AND OLD.status!='active' AND (EXISTS (SELECT 1 FROM declared_parking_reservations r JOIN vehicles v ON v.id=NEW.vehicle_id\n WHERE r.status='confirmed' AND r.arrival_deadline>NEW.check_in_time AND r.end_at>NEW.check_in_time\n AND r.slot_id=NEW.parking_slot_id AND r.start_at<COALESCE((SELECT MAX(bound.end_at) FROM (SELECT r.end_at FROM parking_reservations r JOIN vehicles v ON v.id=r.vehicle_id WHERE r.slot_id=NEW.parking_slot_id AND r.vehicle_id=NEW.vehicle_id AND r.customer_id=v.customer_id AND r.status='confirmed' AND r.start_at<=NEW.check_in_time AND r.arrival_deadline>NEW.check_in_time UNION ALL SELECT a.end_at FROM guaranteed_allocations a JOIN vehicles v ON v.id=a.vehicle_id WHERE a.slot_id=NEW.parking_slot_id AND a.vehicle_id=NEW.vehicle_id AND a.customer_id=v.customer_id AND a.status='active' AND a.start_at<=NEW.check_in_time AND a.end_at>NEW.check_in_time UNION ALL SELECT d.end_at FROM declared_parking_reservations d JOIN vehicles v ON v.id=NEW.vehicle_id WHERE d.slot_id=NEW.parking_slot_id AND d.normalized_plate=replace(replace(replace(upper(v.license_plate),'-',''),'.',''),' ','') AND d.vehicle_type_id=v.vehicle_type_id AND d.status='confirmed' AND d.start_at<=NEW.check_in_time AND d.arrival_deadline>NEW.check_in_time AND d.end_at>NEW.check_in_time) bound), '9999-12-31') AND NOT (r.normalized_plate=replace(replace(replace(upper(v.license_plate),'-',''),'.',''),' ','')\n AND r.vehicle_type_id=v.vehicle_type_id AND r.start_at<=NEW.check_in_time))) THEN RAISE EXCEPTION 'slot has declared booking' USING ERRCODE='23514'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;\nCREATE OR REPLACE FUNCTION trg_session_capacity_hold_fn() RETURNS trigger AS $$\nBEGIN\n    \n    IF NEW.status='active' AND EXISTS (SELECT 1 FROM parking_capacity_holds h WHERE h.slot_id=NEW.parking_slot_id AND h.status='held' AND h.expires_at>(clock_timestamp() AT TIME ZONE 'Asia/Ho_Chi_Minh') AND h.start_at < COALESCE((SELECT MAX(bound.end_at) FROM (SELECT r.end_at FROM parking_reservations r JOIN vehicles v ON v.id=r.vehicle_id WHERE r.slot_id=NEW.parking_slot_id AND r.vehicle_id=NEW.vehicle_id AND r.customer_id=v.customer_id AND r.status='confirmed' AND r.start_at<=NEW.check_in_time AND r.arrival_deadline>NEW.check_in_time UNION ALL SELECT a.end_at FROM guaranteed_allocations a JOIN vehicles v ON v.id=a.vehicle_id WHERE a.slot_id=NEW.parking_slot_id AND a.vehicle_id=NEW.vehicle_id AND a.customer_id=v.customer_id AND a.status='active' AND a.start_at<=NEW.check_in_time AND a.end_at>NEW.check_in_time UNION ALL SELECT d.end_at FROM declared_parking_reservations d JOIN vehicles v ON v.id=NEW.vehicle_id WHERE d.slot_id=NEW.parking_slot_id AND d.normalized_plate=replace(replace(replace(upper(v.license_plate),'-',''),'.',''),' ','') AND d.vehicle_type_id=v.vehicle_type_id AND d.status='confirmed' AND d.start_at<=NEW.check_in_time AND d.arrival_deadline>NEW.check_in_time AND d.end_at>NEW.check_in_time) bound), '9999-12-31')) THEN RAISE EXCEPTION 'slot has a live payment hold' USING ERRCODE='23514'; END IF;\n    RETURN NEW;\nEND; $$ LANGUAGE plpgsql;\n\n        CREATE OR REPLACE FUNCTION parkingai_validate_session()\n        RETURNS trigger LANGUAGE plpgsql AS $$\n        DECLARE\n            session_vehicle_type integer;\n            session_zone integer;\n        BEGIN\n            -- One lock order for every admission path: vehicle -> type ->\n            -- slot -> zone. Price updates share the type lock; slot/zone\n            -- updates share their row locks. This closes cross-container\n            -- check-then-act races under READ COMMITTED.\n            SELECT vehicle_type_id INTO session_vehicle_type\n            FROM vehicles WHERE id = NEW.vehicle_id FOR UPDATE;\n            PERFORM 1 FROM vehicle_types\n            WHERE id = session_vehicle_type FOR SHARE;\n            IF NEW.parking_slot_id IS NOT NULL THEN\n                SELECT zone_id INTO session_zone FROM parking_slots\n                WHERE id = NEW.parking_slot_id FOR UPDATE;\n                PERFORM 1 FROM zones WHERE id = session_zone FOR SHARE;\n            END IF;\n\n            IF TG_OP = 'UPDATE' THEN\n                IF NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id\n                   OR NEW.parking_slot_id IS DISTINCT FROM OLD.parking_slot_id\n                   OR NEW.monthly_pass_id IS DISTINCT FROM OLD.monthly_pass_id\n                   OR NEW.check_in_time IS DISTINCT FROM OLD.check_in_time\n                   OR NEW.staff_in_id IS DISTINCT FROM OLD.staff_in_id THEN\n                    RAISE EXCEPTION 'parking session identity is immutable';\n                END IF;\n\n                IF OLD.status = 'completed' AND (\n                    NEW.status IS DISTINCT FROM OLD.status\n                    OR NEW.check_out_time IS DISTINCT FROM OLD.check_out_time\n                    OR NEW.parking_fee IS DISTINCT FROM OLD.parking_fee\n                    OR NEW.staff_out_id IS DISTINCT FROM OLD.staff_out_id\n                ) THEN\n                    RAISE EXCEPTION 'completed parking session is immutable';\n                END IF;\n\n                IF NEW.status = 'checking_out' AND OLD.status <> 'active' THEN\n                    RAISE EXCEPTION 'parking session status invalid';\n                END IF;\n                IF OLD.status = 'checking_out' AND NEW.status <> 'completed' THEN\n                    RAISE EXCEPTION 'parking session status invalid';\n                END IF;\n            ELSIF NEW.status = 'checking_out' THEN\n                RAISE EXCEPTION 'parking session status invalid';\n            END IF;\n\n            -- Entitlement is a check-in snapshot. Deactivating a pass later\n            -- must not prevent the already-admitted session from completing.\n            IF TG_OP = 'INSERT' AND NEW.monthly_pass_id IS NOT NULL AND NOT EXISTS (\n                SELECT 1 FROM monthly_passes mp\n                WHERE mp.id = NEW.monthly_pass_id\n                  AND mp.vehicle_id = NEW.vehicle_id\n                  AND mp.is_active\n                  AND mp.start_date <= NEW.check_in_time::date\n                  AND mp.end_date >= NEW.check_in_time::date\n            ) THEN\n                RAISE EXCEPTION 'monthly pass is not eligible at check-in';\n            END IF;\n\n            IF NEW.status = 'active' AND NEW.billing_policy_version IS NULL AND NOT EXISTS (\n                SELECT 1 FROM price_configs pc\n                WHERE pc.vehicle_type_id = session_vehicle_type AND pc.is_active\n                  AND pc.effective_date <= NEW.check_in_time::date\n            ) THEN\n                RAISE EXCEPTION 'active parking session requires effective price config';\n            END IF;\n\n            IF NEW.status = 'active' AND NEW.parking_slot_id IS NOT NULL\n               AND NOT EXISTS (\n                SELECT 1 FROM parking_slots ps\n                JOIN zones z ON z.id = ps.zone_id\n                JOIN vehicles v ON v.id = NEW.vehicle_id\n                WHERE ps.id = NEW.parking_slot_id\n                  AND ps.vehicle_type_id = v.vehicle_type_id\n                  AND ps.is_active AND z.is_active\n            ) THEN\n                RAISE EXCEPTION 'parking slot is not eligible for active session';\n            END IF;\n            RETURN NEW;\n        END;\n        $$;\n"


